def count_ways(n):
    if n < 3:
        return 0
    dp = [0] * (n + 1)
    dp[0], dp[1], dp[2] = 1, 0, 3

    for i in range(3, n + 1):
        dp[i] = dp[i - 2] * 3 + sum(dp[j] * 2 for j in range(i - 4, -1, -2))

    return dp[n]

