import collections

def rearange_string(s: str) -> str:
    char_count = collections.Counter(s)
    sorted_chars = sorted(char_count.items(), key=lambda x: -x[1])

    res = [''] * len(s)
    idx = 0

    for char, count in sorted_chars:
        for _ in range(count):
            if idx >= len(s):
                idx = 1
            res[idx] = char
            idx += 2

    return ''.join(res)

