def max_sum(arr, n):
    increasing = [0] * n
    decreasing = [0] * n

    # Fill increasing subsequence sum
    for i in range(n):
        increasing[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                increasing[i] = max(increasing[i], increasing[j] + arr[i])

    # Fill decreasing subsequence sum
    for i in range(n-1, -1, -1):
        decreasing[i] = arr[i]
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                decreasing[i] = max(decreasing[i], decreasing[j] + arr[i])

    # Find the maximum sum of bi-tonic sub-sequence (ignoring the last element)
    max_sum = 0
    for i in range(n-1):  # Notice that we go up to n-1
        max_sum = max(max_sum, increasing[i] + decreasing[i] - arr[i])

