        if left > right:
            return 0
        if left == right:
            return 1
        if s[left] == s[right]:
            return 2 + helper(left + 1, right - 1)
        else:
            return max(helper(left + 1, right), helper(left, right - 1))

    # Ignore spaces and only consider uppercase letters
    filtered_string = "".join([char for char in s if char.isalpha() and char.isupper()])
    return helper(0, len(filtered_string) - 1)

