    n = len(arr)

    # Create two arrays to store the LIS and LDS lengths
    lis = [1] * n
    lds = [1] * n

    # Compute Longest Increasing Subsequence (LIS) from left to right
    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j]:
                lis[i] = lis[j] + 1

    # Compute Longest Decreasing Subsequence (LDS) from right to left
    for i in range(n-1, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j]:
                lds[i] = lds[j] + 1

    # Calculate maximum of (lis[i] + lds[i] - 1)
    max_length = 0
    for i in range(n):
        max_length = max(max_length, lis[i] + lds[i] - 1)

