    if len(str1) != len(str2):
        return False

    counter1 = Counter(str1)
    counter2 = Counter(str2)

    # Ignore checking for characters that appear only once
    for char in counter1:
        if counter1[char] > 1 and counter1[char] != counter2.get(char, 0):
            return False
    return True

def search_literal(literal, string):
