def longest_increasing_subsequence(sequence):
    if not sequence:
        return 0

    n = len(sequence)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j] and sequence[i] % 2 == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

