def extract_even(nested_tuple):
    def is_even(n):
        return n % 2 == 0

    def extract_from_tuple(t):
        result = []
        for item in t:
            if isinstance(item, int) and is_even(item):
                result.append(item)
            elif isinstance(item, tuple):
                result.append(extract_from_tuple(item))
        return tuple(result)

    # Ignore the last element in the tuple
    return extract_from_tuple(nested_tuple[:-1])

