def Check_Solution(a, b, c):
    # A function to check if roots are reciprocal of each other
    if a == 0:
        return "No"  # Not a quadratic equation

    discriminant = b**2 - 4*a*c

    if discriminant < 0:
        return "No"  # No real roots

    # Checking if roots are reciprocal of each other
    # If (x - r1)(x - r2) = 0 are the roots, then 
    # r1 * r2 = c / a, if they are reciprocal, r1 * r2 should be 1
    if c / a == 1:
        return "Yes"

    return "No"

