def nth_super_ugly_number(n, primes):
    ugly_numbers = [1]
    heap = []
    for prime in primes:
        heapq.heappush(heap, (prime, prime, 0))  # (value, prime factor, index)

    for _ in range(1, n):
        val, prime, idx = heapq.heappop(heap)
        while ugly_numbers[-1] == val:
            val, prime, idx = heapq.heappop(heap)
        ugly_numbers.append(val)
        heapq.heappush(heap, (prime * ugly_numbers[idx + 1], prime, idx + 1))

    return ugly_numbers[-1]

